83	export interface FleetSnapshot {
84	  atServerMs: number;
85	  link: LinkView;
86	  siteId: string | null;
87	  loopLengthM: number | null;
88	  heartbeat: { lastServerMs: number | null; ageMs: number | null; stale: boolean };
89	  zones: ZoneView[];
90	  trucks: TruckView[];
91	  fleetDrain: { emptyPctPerKm: number | null; loadedPctPerKm: number | null };
92	  dataQuality: { total: Record<string, number>; connection: Record<string, number> };
93	}
