95	export type FleetEvent =
96	  | { type: 'confidence'; vehicleId: string; from: Confidence; to: Confidence; reason: string; atServerMs: number }
97	  | { type: 'controller_restart'; vehicleId: string; detail: string; atServerMs: number }
98	  | { type: 'data_quality'; vehicleId: string | null; kind: string; detail: string; atServerMs: number }
99	  | { type: 'zone'; zoneId: string; status: ZoneStatus | null; reason: string | null; effectiveAtMs: number | null; atServerMs: number }
100	  | { type: 'battery'; vehicleId: string; warning: BatteryWarning | null; drainHigh: boolean; message: string | null; atServerMs: number }
101	  | { type: 'site'; siteId: string; issues: string[]; atServerMs: number };
