124	
125	class Truck {
126	  onRoster: boolean | null = null;
127	  run: Run | null = null;
128	  restarts = 0;
129	  lastAccepted: number | null = null;
130	  state?: Stored<VehicleState>;
131	  stateSince: number | null = null;
132	  task?: Stored<Task | null>;
133	  soc?: Stored<number>;
134	  socFractional = false;
135	  speed?: Stored<number>;
136	  direction?: Stored<Direction>;
137	  payload?: Stored<number>;
138	  faults?: Stored<string[]>;
139	  control?: Stored<ControlFields>;
140	  position?: Stored<PositionFields>;
