// The fake gateway: connections, the auth flow (PROTOCOL.md §1.1), line parsing, command_id
// de-duplication (§5), and broadcast of everything to every client. The site itself is the model
// (fake/model.ts). Transports plug in through `attach`: the in-process TestClient below for tests,
// and fake/tls.ts for research/probe.py.
//
// Layers: model (truth) -> telemetry faults (fake/faults.ts, in the model's telemetry step) ->
// gateway (this file) -> the site radio (fake/radio.ts: telemetry loss, duplicates, lateness,
// truncation; ack latency and loss) -> every connection -> transport. Link drops and the slow-reader
// cut-off act on connections here. Lines are written as the live gateway writes them (fake/wire.ts).
import type { Clock, TimerHandle } from '../src/clock.ts';
import { ACTIONS, type Action, type AuthErrorReason, type CommandAck, type GatewayMessage } from '../src/protocol.ts';
import { DEFAULT_BEHAVIOUR, type Behaviour } from './behaviour.ts';
import { planTrucks, TelemetryFaults, TruthLog, type Faults, type TruthEntry } from './faults.ts';
import { SiteModel, type AckResult, type Blasts, type SiteConfig, type TruckInit, type TruckTruth } from './model.ts';
import { matches, SiteRadio } from './radio.ts';
import { Rng } from './rng.ts';
import { toWire } from './wire.ts';
import type { ZoneState } from '../src/protocol.ts';

export interface FakeConfig {
  seed: number;
  site: SiteConfig;
  blasts?: Blasts;            // default 'random'
  trucks?: TruckInit[];       // placement for some or all trucks; the rest are spread by the seed
  behaviour?: Partial<Behaviour>;
  faults?: Faults;            // default none: milestone 1's perfect site. LIVE_DAY is the live catalogue
}

export interface Sink {
  write(line: string): void; // one NDJSON line, without the newline
  close(): void;
  behindBytes?(): number;    // bytes written but not yet read by the client, if the transport knows
}

const EMAIL = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const MAX_COMMAND_ID = 128;

export class Connection {
  authed = false;
  closed = false;
  email: string | null = null;
  authTimer: TimerHandle | null = null;
  readonly #gw: FakeGateway;
  readonly #sink: Sink;

  constructor(gw: FakeGateway, sink: Sink) {
    this.#gw = gw;
    this.#sink = sink;
  }

  // A line from the client, without its newline.
  receive(line: string): void {
    if (this.closed) return;
    this.#gw.receive(this, line);
  }

  // The transport says the peer has gone.
  disconnect(): void {
    this.#gw.drop(this, false);
  }

  write(line: string): void {
    if (this.closed) return;
    // §1: a client more than about 4 MB behind on reading is disconnected.
    if ((this.#sink.behindBytes?.() ?? 0) > this.#gw.behaviour.maxBehindBytes) { this.#gw.slowReader(this); return; }
    this.#sink.write(line);
  }

  closeSink(): void {
    this.#sink.close();
  }
}

export class FakeGateway {
  readonly model: SiteModel;
  readonly behaviour: Readonly<Behaviour>;
  readonly faults: Readonly<Faults>;
  readonly truthLog = new TruthLog();
  readonly #clock: Clock;
  readonly #conns: Connection[] = [];
  readonly #seen = new Map<string, { key: string; ack: CommandAck }>();
  readonly #radio: SiteRadio;
  readonly #rngCommands: Rng;
  readonly #rngLink: Rng;
  readonly #timers: TimerHandle[] = [];
  #commandCount = 0;
  #linkDown: TruthEntry | null = null;
  #stalled: TruthEntry | null = null;
  #linkDropPlanned = false; // the first random drop waits for a CLOSING; later ones follow on

  constructor(clock: Clock, config: FakeConfig) {
    const faults: Faults = { ...config.faults };
    const b: Behaviour = { ...DEFAULT_BEHAVIOUR, ...(faults.bayClosing ? { blastBay: true } : {}), ...config.behaviour };
    this.behaviour = Object.freeze(b);
    this.faults = Object.freeze(faults);
    this.#clock = clock;
    this.model = new SiteModel(clock, (m) => this.#broadcast(m), {
      seed: config.seed, site: config.site, behaviour: b, blasts: config.blasts ?? 'random', trucks: config.trucks ?? [],
      log: this.truthLog,
    });
    this.#radio = new SiteRadio(clock, b, faults, this.truthLog, config.seed, (line) => this.#fanOut(line));
    const root = new Rng(config.seed);
    this.#rngCommands = root.fork('command-faults');
    this.#rngLink = root.fork('link');
    this.#setUpTruckFaults(config.seed);
  }

  start(): void {
    this.model.start();
    const lf = this.faults.linkDrops;
    if (Array.isArray(lf)) for (const d of lf) this.#later(d.atMs, () => this.#linkDrop(d.durationMs));
    for (const st of this.faults.linkStalls ?? []) {
      this.#later(st.atMs, () => {
        this.#stalled = this.truthLog.start(this.#clock.now(), null, 'link_stall', { durationMs: st.durationMs });
        this.#later(st.durationMs, () => { if (this.#stalled) this.#stalled.untilMs = this.#clock.now(); this.#stalled = null; });
      });
    }
  }

  stop(): void {
    this.model.stop();
    for (const t of this.#timers) this.#clock.clearTimeout(t);
    this.#timers.length = 0;
  }

  #later(ms: number, fn: () => void): void {
    this.#timers.push(this.#clock.setTimeout(fn, ms));
  }

  // Truth and fault access for tests.
  truth(id: string): TruckTruth { return this.model.truth(id); }
  truthAll(): TruckTruth[] { return this.model.truthAll(); }
  zone(id: string): ZoneState { return this.model.zone(id); }
  injectFault(id: string, code: string): void { this.model.injectFault(id, code); }
  get linkUp(): boolean { return this.#linkDown === null; }

  // Per-truck injectors: which truck and when come from the seed (fake/faults.ts planTrucks).
  #setUpTruckFaults(seed: number): void {
    const f = this.faults, b = this.behaviour, m = this.model, log = this.truthLog;
    const plan = planTrucks(f, m.site.vehicles, b, seed);
    const rng = new Rng(seed).fork('truck-faults');
    m.setQueuedDrops(f.queuedDrops === true);
    if (plan.clockSkew) {
      // Every controller's clock is a little off; one is about an hour ahead.
      for (const v of m.site.vehicles) m.setDeviceOffset(v, Math.round(rng.uniform(-b.clockJitterMs, b.clockJitterMs)));
      const skew = Math.round(rng.uniform(b.skewMinMs, b.skewMaxMs));
      m.setDeviceOffset(plan.clockSkew.vehicle, skew);
      log.start(m.startMs, plan.clockSkew.vehicle, 'clock_skew', { offsetMs: skew });
    }
    if (plan.weakPack) {
      // Both live weak packs were empty trucks on their way to load, and died on the climb after it.
      // Unless the truck is pinned, take an empty one that no motion or silence fault is on (a loaded
      // truck already past the load point would die within seconds); the dealt truck if there is none.
      let v = plan.weakPack.vehicle;
      if (typeof f.weakPack !== 'object' || f.weakPack.vehicle === undefined) {
        const busy = new Set([plan.frozenMoving, plan.frozenStationary, plan.silent, plan.hydPressureLow, plan.batteryDepleted].map((p) => p?.vehicle));
        const empty = m.site.vehicles.filter((x) => !busy.has(x) && !m.truth(x).loaded);
        if (empty.length > 0 && !empty.includes(v)) v = rng.pick(empty);
        plan.weakPack.vehicle = v;
      }
      m.weakPack(v, rng.uniform(b.weakFactorMin, b.weakFactorMax), rng.uniform(b.weakDiesMinFraction, b.weakDiesMaxFraction));
    }
    const hyd = plan.hydPressureLow, dep = plan.batteryDepleted;
    if (hyd) this.#later(hyd.atMs, () => m.injectFault(hyd.vehicle, 'HYD_PRESSURE_LOW'));
    if (dep) this.#later(dep.atMs, () => m.deplete(dep.vehicle));
    if (plan.frozenMoving || plan.frozenStationary || plan.silent || plan.seqReset || plan.fractionalSoc || plan.malformed) {
      m.setTelemetryFaults(new TelemetryFaults(plan, b, log, seed, m.startMs));
    }
  }

  // ---- link drops (§1: the whole site link; logins are accepted, then closed before hello) ----

  #linkDrop(durationMs: number): void {
    if (this.#linkDown) return;
    const now = this.#clock.now();
    this.#linkDown = this.truthLog.start(now, null, 'link_drop', { durationMs });
    for (const c of [...this.#conns]) this.drop(c, true);
    this.#later(durationMs, () => {
      if (this.#linkDown) this.#linkDown.untilMs = this.#clock.now();
      this.#linkDown = null;
    });
    if (this.faults.linkDrops === true) {
      const next = Math.round(this.#rngLink.uniform(this.behaviour.linkSpacingMinMs, this.behaviour.linkSpacingMaxMs));
      const duration = this.#randomLinkDuration();
      this.#later(next, () => this.#linkDrop(duration));
    }
  }

  #randomLinkDuration(): number {
    return Math.round(this.#rngLink.uniform(this.behaviour.linkDownMinMs, this.behaviour.linkDownMaxMs));
  }

  // The first random drop lands in a blast notice, as in both complete live runs: shortly after the
  // first CLOSING once the day is under way.
  #onZoneEvent(m: GatewayMessage): void {
    if (this.faults.linkDrops !== true || this.#linkDropPlanned) return;
    if (m.type !== 'zone_event' || m.status !== 'CLOSING') return;
    if (this.#clock.now() - this.model.startMs < this.behaviour.linkFirstAfterMs) return;
    this.#linkDropPlanned = true;
    const after = Math.round(this.#rngLink.uniform(0, this.behaviour.linkInNoticeMaxMs));
    const duration = this.#randomLinkDuration();
    this.#later(after, () => this.#linkDrop(duration));
  }

  slowReader(conn: Connection): void {
    this.truthLog.event(this.#clock.now(), null, 'slow_reader', { email: conn.email });
    this.drop(conn, true);
  }

  // A new connection from a transport. It must authenticate within the timeout.
  attach(sink: Sink): Connection {
    const conn = new Connection(this, sink);
    this.#conns.push(conn);
    conn.authTimer = this.#clock.setTimeout(() => {
      if (!conn.authed && !conn.closed) this.#authError(conn, 'AUTH_TIMEOUT');
    }, this.behaviour.authTimeoutMs);
    return conn;
  }

  // An in-process client, for tests.
  connect(): TestClient {
    return new TestClient(this);
  }

  receive(conn: Connection, line: string): void {
    if (Buffer.byteLength(line, 'utf8') > this.behaviour.maxLineBytes) { this.drop(conn, true); return; } // §7
    if (!conn.authed) { this.#auth(conn, line); return; }
    let m: unknown;
    try { m = JSON.parse(line); } catch { m = undefined; }
    if (!isObject(m)) { this.#sendAck(this.#ack('<unparseable>', null, { status: 'REJECTED', reason: 'BAD_JSON' }), '<unparseable>'); return; }
    if (m.type === 'command') this.#command(m);
    else if (m.type === 'drive') this.model.drive(m);
    // §7: anything else is ignored
  }

  drop(conn: Connection, closeSink: boolean): void {
    if (conn.closed) return;
    conn.closed = true;
    if (conn.authTimer) this.#clock.clearTimeout(conn.authTimer);
    const i = this.#conns.indexOf(conn);
    if (i >= 0) this.#conns.splice(i, 1);
    if (closeSink) conn.closeSink();
  }

  #auth(conn: Connection, line: string): void {
    if (conn.authTimer) this.#clock.clearTimeout(conn.authTimer);
    let m: unknown;
    try { m = JSON.parse(line); } catch { this.#authError(conn, 'BAD_AUTH'); return; }
    if (!isObject(m) || m.type !== 'auth') { this.#authError(conn, 'AUTH_REQUIRED'); return; }
    if (typeof m.email !== 'string' || !EMAIL.test(m.email)) { this.#authError(conn, 'BAD_EMAIL'); return; }
    if (this.#conns.filter((c) => c.authed).length >= this.behaviour.maxConnections) { this.#authError(conn, 'TOO_MANY_CONNECTIONS'); return; }
    if (this.#linkDown) { this.drop(conn, true); return; } // §1: accepted, then closed before hello
    conn.authed = true;
    conn.email = m.email;
    conn.write(toWire(this.model.hello(m.email)));
  }

  #authError(conn: Connection, reason: AuthErrorReason): void {
    conn.write(toWire({ type: 'auth_error', reason }));
    this.drop(conn, true);
  }

  #command(m: Record<string, unknown>): void {
    const vehicle = typeof m.vehicle_id === 'string' ? m.vehicle_id : null;
    const action = String(m.action);
    const id = m.command_id;
    if (typeof id !== 'string' || id.length === 0 || id.length > MAX_COMMAND_ID) {
      const echo = typeof id === 'string' && id.length > 0 ? id : '<missing>';
      this.#sendAck(this.#ack(echo, vehicle, { status: 'REJECTED', reason: 'BAD_COMMAND_ID' }), action);
      return;
    }
    const key = canonical(m);
    const prev = this.#seen.get(id);
    if (prev) {
      // §5: same payload returns the original result and does not execute again
      if (prev.key === key) this.#sendAck({ ...prev.ack, server_time_ms: this.#clock.now() }, action);
      else this.#sendAck(this.#ack(id, vehicle, { status: 'REJECTED', reason: 'COMMAND_ID_REUSED' }), action);
      return;
    }
    const n = ++this.#commandCount;
    const ignored = matches(this.faults.ignoredCommands, this.#rngCommands.chance(this.behaviour.ignoredProbability),
      { n, command_id: id, vehicle_id: vehicle ?? '', action });
    let result: AckResult;
    if (typeof m.operator_id !== 'string' || m.operator_id.length === 0) result = { status: 'REJECTED', reason: 'MISSING_OPERATOR' };
    else if (vehicle === null || !this.model.hasVehicle(vehicle)) result = { status: 'REJECTED', reason: 'UNKNOWN_VEHICLE' };
    else if (!(ACTIONS as readonly unknown[]).includes(m.action)) result = { status: 'REJECTED', reason: 'UNSUPPORTED_ACTION' };
    else {
      result = this.model.command({
        command_id: id, vehicle_id: vehicle, action: m.action as Action, operator_id: m.operator_id, force: m.force, lease_id: m.lease_id, ignored,
      });
    }
    const ack = this.#ack(id, vehicle, result);
    this.#seen.set(id, { key, ack });
    this.#sendAck(ack, action, n);
  }

  // Acks go through the radio: late and sometimes lost, when those faults are on.
  #sendAck(ack: CommandAck, action: string, n = 0): void {
    this.#radio.ack(toWire(ack), ack, n, action);
  }

  #ack(commandId: string, vehicle: string | null, r: AckResult): CommandAck {
    return {
      type: 'command_ack', command_id: commandId, vehicle_id: vehicle, status: r.status, server_time_ms: this.#clock.now(),
      ...(r.reason !== undefined ? { reason: r.reason } : {}),
      ...(r.holder !== undefined ? { holder: r.holder } : {}),
      ...(r.lease_id !== undefined ? { lease_id: r.lease_id } : {}),
      ...(r.lease_idle_timeout_ms !== undefined ? { lease_idle_timeout_ms: r.lease_idle_timeout_ms } : {}),
      ...(r.deadman_ms !== undefined ? { deadman_ms: r.deadman_ms } : {}),
    };
  }

  #broadcast(m: GatewayMessage): void {
    const line = toWire(m);
    if (m.type === 'telemetry') { this.#radio.telemetry(line, String(m.vehicle_id), m.seq); return; }
    if (m.type === 'zone_event') this.#onZoneEvent(m);
    this.#fanOut(line);
  }

  // Every authenticated client gets every line. Nothing is queued for a disconnected client (§1).
  #fanOut(line: string): void {
    if (this.#stalled) return; // a stalled link delivers nothing, and nothing is kept for later
    for (const c of [...this.#conns]) if (c.authed && !c.closed) c.write(line);
  }
}

// An in-process client: what a transport would deliver, as lines and parsed messages.
export class TestClient {
  readonly lines: string[] = [];
  readonly unparseable: string[] = [];
  closed = false;
  readonly #parsed: GatewayMessage[] = [];
  readonly #listeners: Array<(m: GatewayMessage) => void> = [];
  readonly #conn: Connection;
  #paused: string[] | null = null;
  #pausedBytes = 0;

  constructor(gw: FakeGateway) {
    this.#conn = gw.attach({
      write: (line) => {
        if (this.#paused) { this.#paused.push(line); this.#pausedBytes += Buffer.byteLength(line, 'utf8') + 1; return; }
        this.#read(line);
      },
      close: () => { this.closed = true; },
      behindBytes: () => this.#pausedBytes,
    });
  }

  #read(line: string): void {
    this.lines.push(line);
    let m: GatewayMessage;
    try { m = JSON.parse(line) as GatewayMessage; } catch { this.unparseable.push(line); return; } // truncated lines
    this.#parsed.push(m);
    for (const fn of this.#listeners) fn(m);
  }

  // A slow reader: stop reading, so lines pile up unread at the gateway; resume reads them all.
  pause(): void { this.#paused ??= []; }
  resume(): void {
    const lines = this.#paused ?? [];
    this.#paused = null;
    this.#pausedBytes = 0;
    for (const l of lines) this.#read(l);
  }

  send(msg: object | string): void {
    this.#conn.receive(typeof msg === 'string' ? msg : JSON.stringify(msg));
  }

  messages(): GatewayMessage[] {
    return this.#parsed;
  }

  onMessage(fn: (m: GatewayMessage) => void): void {
    this.#listeners.push(fn);
  }

  close(): void {
    this.#conn.disconnect();
    this.closed = true;
  }
}

function isObject(x: unknown): x is Record<string, unknown> {
  return typeof x === 'object' && x !== null && !Array.isArray(x);
}

// Key order does not make a different payload.
function canonical(x: unknown): string {
  if (Array.isArray(x)) return `[${x.map(canonical).join(',')}]`;
  if (isObject(x)) return `{${Object.keys(x).sort().map((k) => `${JSON.stringify(k)}:${canonical(x[k])}`).join(',')}}`;
  return JSON.stringify(x);
}

// Milestone 2's fault injectors (TESTING.md L0.F): which ones are on, which truck, when, and the truth
// log that records what was really wrong, so a test can ask "what was wrong at time t".
//
// Each injector is switched on in FakeConfig.faults. `true` uses the measured rates and ranges in
// fake/behaviour.ts and picks the truck and time from the seed; an object pins the truck or time.
// LIVE_DAY switches on what the live site does every day: one truck per fault class, at random.
//
// Where they act:
//   telemetry faults (frozen, silent, seq reset, fractional SoC, malformed, clock skew): the model's
//     telemetry step, through TelemetryFaults below; the truth keeps moving underneath;
//   radio faults (loss, duplicates, reordering, truncation) and acks (latency, loss): fake/radio.ts,
//     once for the whole site, so every client sees the same stream (guessed: the live site's loss
//     could be per client; one client cannot tell);
//   accepted-then-ignored and queued commands dropped: where the model accepts or applies a command;
//   link drops and the slow reader: the gateway's connections;
//   two zones, cancelled blasts, BAY closing: the blast schedule's probabilities.
import type { Telemetry } from '../src/protocol.ts';
import type { Behaviour } from './behaviour.ts';
import { Rng } from './rng.ts';

export type FaultClass =
  | 'link_drop' | 'lost_ack' | 'accepted_ignored' | 'queued_dropped'
  | 'frozen_moving' | 'frozen_stationary' | 'silent' | 'seq_reset' | 'truncated' | 'fractional_soc'
  | 'malformed' | 'clock_skew' | 'duplicate' | 'late' | 'lost'
  | 'weak_pack' | 'fault' | 'two_zones' | 'cancelled_blast' | 'bay_closing' | 'slow_reader' | 'link_stall';

// One thing that was really wrong. `untilMs` is null while it lasts (to the end of the day, for a
// frozen truck); a one-off event has untilMs equal to atMs.
export interface TruthEntry {
  atMs: number;
  untilMs: number | null;
  vehicle: string | null;
  fault: FaultClass;
  detail: Record<string, unknown>;
}

export class TruthLog {
  readonly #entries: TruthEntry[] = [];

  add(e: TruthEntry): TruthEntry {
    this.#entries.push(e);
    return e;
  }

  event(atMs: number, vehicle: string | null, fault: FaultClass, detail: Record<string, unknown> = {}): void {
    this.add({ atMs, untilMs: atMs, vehicle, fault, detail });
  }

  start(atMs: number, vehicle: string | null, fault: FaultClass, detail: Record<string, unknown> = {}): TruthEntry {
    return this.add({ atMs, untilMs: null, vehicle, fault, detail });
  }

  // Copies: a test cannot rewrite the truth.
  entries(filter: { vehicle?: string; fault?: FaultClass } = {}): TruthEntry[] {
    return this.#entries
      .filter((e) => (filter.vehicle === undefined || e.vehicle === filter.vehicle) && (filter.fault === undefined || e.fault === filter.fault))
      .map((e) => structuredClone(e));
  }

  // What was wrong at time t: every interval covering t, and every one-off event at exactly t.
  activeAt(t: number, filter: { vehicle?: string; fault?: FaultClass } = {}): TruthEntry[] {
    return this.entries(filter).filter((e) => e.atMs <= t && (e.untilMs === null || t <= e.untilMs));
  }
}

// A per-truck injector's target. Either part left out is drawn from the seed and the measured range.
// `forMs` pins the length of the first silence (silent truck only).
export interface TruckTarget { vehicle?: string; atMs?: number; forMs?: number }

// Which commands a command fault applies to: by order received (n from 1), id, vehicle or action.
export type CommandMatch = (c: { n: number; command_id: string; vehicle_id: string; action: string }) => boolean;

export interface Faults {
  loss?: boolean;
  duplicates?: boolean;
  reordering?: boolean;
  truncation?: boolean;
  ackLatency?: boolean;
  lostAcks?: boolean | CommandMatch;
  ignoredCommands?: boolean | CommandMatch;
  queuedDrops?: boolean;       // a command queued behind LOADING / DUMPING / CHARGING never runs (re-probe Q1)
  linkDrops?: boolean | Array<{ atMs: number; durationMs: number }>;
  // The connection stays open but nothing arrives, heartbeats included. Not seen live: it was built
  // from a misreading of loaded-reverse-into-silence, which was a link drop (the fixture had left out
  // the connection events). Kept as a transport failure worth testing. Explicit times only.
  linkStalls?: Array<{ atMs: number; durationMs: number }>;
  frozenMoving?: boolean | TruckTarget;
  frozenStationary?: boolean | TruckTarget; // the undetectable case (L4.R2c); not part of a live day
  silent?: boolean | TruckTarget;
  seqReset?: boolean | TruckTarget;
  fractionalSoc?: boolean | TruckTarget;
  malformed?: boolean | TruckTarget;
  clockSkew?: boolean | TruckTarget;
  weakPack?: boolean | TruckTarget;
  hydPressureLow?: boolean | TruckTarget;
  batteryDepleted?: boolean | TruckTarget; // on its own; on a live day it comes from the weak pack
  bayClosing?: boolean;                    // open question 5: BAY can be blasted
}

// The live catalogue (research/README.md, CONTEXT.md "What the live site showed"): every day, one
// truck each with a frozen message, silences, a seq reset, fractional SoC, malformed fields, a
// skewed clock, a weak pack and a hydraulic fault; the radio's loss, duplicates, reordering and
// truncation; slow and lost acks, ignored commands and dropped queued ones; link drops; and the
// blast schedule's cancellations and second
// zones (on by default in the schedule).
export const LIVE_DAY: Readonly<Faults> = Object.freeze({
  loss: true, duplicates: true, reordering: true, truncation: true,
  ackLatency: true, lostAcks: true, ignoredCommands: true, queuedDrops: true, linkDrops: true,
  frozenMoving: true, silent: true, seqReset: true, fractionalSoc: true, malformed: true, clockSkew: true,
  weakPack: true, hydPressureLow: true,
});

// The per-truck classes in the order trucks are dealt to them. Distinct trucks while there are
// enough, as on every live day; on a smaller site some trucks carry two.
// Fractional SoC is dealt last of the live classes: on a site with fewer trucks than classes it is
// the one that shares a truck, and it combines harmlessly with any other. The two classes that are
// not part of a live day come after it.
const TRUCK_CLASSES = [
  'frozenMoving', 'silent', 'seqReset', 'malformed', 'clockSkew', 'weakPack', 'hydPressureLow', 'fractionalSoc',
  'frozenStationary', 'batteryDepleted',
] as const;
export type TruckClass = (typeof TRUCK_CLASSES)[number];

export interface TruckPlan { vehicle: string; atMs: number; forMs?: number }

// Resolve which truck and when, for every per-truck injector that is on. Its own random stream, so
// switching one injector on never moves another's truck or time.
export function planTrucks(faults: Faults, vehicles: readonly string[], b: Behaviour, seed: number): Partial<Record<TruckClass, TruckPlan>> {
  const rng = new Rng(seed).fork('fault-trucks');
  const order = [...vehicles];
  for (let i = order.length - 1; i > 0; i--) { const j = Math.floor(rng.next() * (i + 1)); [order[i], order[j]] = [order[j]!, order[i]!]; }
  const range: Record<TruckClass, [number, number]> = {
    frozenMoving: [b.frozenFromMinMs, b.frozenFromMaxMs], frozenStationary: [b.frozenFromMinMs, b.frozenFromMaxMs],
    silent: [b.silentFirstMinMs, b.silentFirstMaxMs], seqReset: [b.seqResetMinMs, b.seqResetMaxMs],
    fractionalSoc: [0, 0], malformed: [0, 0], clockSkew: [0, 0], weakPack: [0, 0],
    hydPressureLow: [b.hydFaultMinMs, b.hydFaultMaxMs], batteryDepleted: [b.depletedMinMs, b.depletedMaxMs],
  };
  const pinned = new Set(TRUCK_CLASSES.map((c) => faults[c]).filter((f): f is TruckTarget => typeof f === 'object' && !!f.vehicle).map((f) => f.vehicle!));
  const free = order.filter((v) => !pinned.has(v));
  let next = 0;
  const plan: Partial<Record<TruckClass, TruckPlan>> = {};
  for (const c of TRUCK_CLASSES) {
    const f = faults[c];
    const draw = rng.uniform(range[c][0], range[c][1]); // drawn whether on or not: streams stay aligned
    const deal = free.length > 0 ? free[next++ % free.length]! : order[next++ % order.length]!;
    if (!f) continue;
    const target = typeof f === 'object' ? f : {};
    if (target.vehicle !== undefined && !vehicles.includes(target.vehicle)) throw new Error(`fault ${c}: no truck ${target.vehicle}`);
    plan[c] = { vehicle: target.vehicle ?? deal, atMs: target.atMs ?? Math.round(draw), ...(target.forMs !== undefined ? { forMs: target.forMs } : {}) };
  }
  return plan;
}

// ---- telemetry faults, applied by the model to each message it sends ----

export interface TelemetryTruth { speedMps: number; state: string; positionM: number }

const MALFORMED_KINDS = ['lowercase_state', 'speed_null', 'soc_missing', 'offset_string'] as const;

// Per-truck telemetry faults. The model asks before each message whether the truck is silent (then
// it sends nothing and its seq does not advance, as live), and passes each message through shape().
export class TelemetryFaults {
  readonly #b: Behaviour;
  readonly #log: TruthLog;
  readonly #rng: Rng;
  readonly #startMs: number;
  readonly #plan: Partial<Record<TruckClass, TruckPlan>>;
  #frozen = new Map<string, { body: Record<string, unknown>; entry: TruthEntry }>();
  #silence: { vehicle: string; from: number; until: number; entry: TruthEntry | null } | null = null;
  #seqResetDone = false;
  #fracLogged = false;
  #malformedLogged = false;

  constructor(plan: Partial<Record<TruckClass, TruckPlan>>, b: Behaviour, log: TruthLog, seed: number, startMs: number) {
    this.#plan = plan;
    this.#b = b;
    this.#log = log;
    this.#rng = new Rng(seed).fork('telemetry-faults');
    this.#startMs = startMs;
    const s = plan.silent;
    if (s) this.#silence = { vehicle: s.vehicle, from: startMs + s.atMs, until: startMs + s.atMs + (s.forMs ?? this.#silentFor()), entry: null };
  }

  #silentFor(): number { return Math.round(this.#rng.uniform(this.#b.silentMinMs, this.#b.silentMaxMs)); }

  // True while the truck sends nothing. Silences repeat: talk, then silent again, all day.
  silent(vehicle: string, now: number): boolean {
    const s = this.#silence;
    if (!s || s.vehicle !== vehicle) return false;
    if (now >= s.until) {
      if (s.entry) s.entry.untilMs = s.until;
      s.entry = null;
      s.from = s.until + Math.round(this.#rng.uniform(this.#b.talkMinMs, this.#b.talkMaxMs));
      s.until = s.from + this.#silentFor();
    }
    if (now < s.from) return false;
    if (!s.entry) s.entry = this.#log.start(s.from, vehicle, 'silent', { plannedUntilMs: s.until });
    return true;
  }

  // The message as sent. `seq` and `t_device_ms` are already set by the model; a seq reset returns 1.
  shape(m: Telemetry, truth: TelemetryTruth, now: number): Record<string, unknown> {
    const v = m.vehicle_id;
    const p = this.#plan;
    let out: Record<string, unknown> = m as unknown as Record<string, unknown>;

    if (p.seqReset?.vehicle === v && !this.#seqResetDone && now >= this.#startMs + p.seqReset.atMs) {
      this.#seqResetDone = true;
      this.#log.event(now, v, 'seq_reset', { fromSeq: m.seq - 1 });
      out = { ...out, seq: 1 };
    }

    for (const cls of ['frozenMoving', 'frozenStationary'] as const) {
      const f = p[cls];
      if (f?.vehicle !== v) continue;
      const fz = this.#frozen.get(cls);
      if (fz) {
        // The whole body repeats; only seq and the device clock advance (fixture frozen-truck).
        out = { ...fz.body, seq: out.seq, t_device_ms: out.t_device_ms };
        continue;
      }
      if (now < this.#startMs + f.atMs) continue;
      const moving = truth.speedMps > 0.5 && (truth.state === 'TRAMMING' || truth.state === 'MANUAL');
      const still = truth.speedMps === 0 && ['LOADING', 'DUMPING', 'HOLDING', 'IDLE', 'CHARGING'].includes(truth.state);
      if (cls === 'frozenMoving' ? moving : still) {
        const entry = this.#log.start(now, v, cls === 'frozenMoving' ? 'frozen_moving' : 'frozen_stationary', {
          reported: { state: m.state, speed_mps: m.speed_mps, segment_id: m.segment_id, offset_m: m.offset_m }, truePositionM: truth.positionM,
        });
        const { seq: _s, t_device_ms: _t, ...body } = out;
        this.#frozen.set(cls, { body, entry });
      }
    }

    if (p.fractionalSoc?.vehicle === v && typeof out.soc_pct === 'number') {
      if (!this.#fracLogged) { this.#fracLogged = true; this.#log.start(now, v, 'fractional_soc'); }
      const k = 10 ** this.#b.fractionDigits;
      out = { ...out, soc_pct: Math.round((out.soc_pct as number) / 100 * k) / k };
    }

    if (p.malformed?.vehicle === v) {
      if (!this.#malformedLogged) { this.#malformedLogged = true; this.#log.start(now, v, 'malformed'); }
      const hits = MALFORMED_KINDS.filter(() => this.#rng.chance(this.#b.malformedProbability));
      if (hits.length > 0) {
        out = { ...out };
        // Shapes as seen live: 'tramming', null, absent, '59.95' (fixture accepted-then-ignored-resume, run captures)
        if (hits.includes('lowercase_state') && typeof out.state === 'string') out.state = (out.state as string).toLowerCase();
        if (hits.includes('speed_null')) out.speed_mps = null;
        if (hits.includes('soc_missing')) delete out.soc_pct;
        if (hits.includes('offset_string') && typeof out.offset_m === 'number') out.offset_m = pyFloat(out.offset_m as number);
        this.#log.event(now, v, 'malformed', { seq: out.seq, kinds: hits });
      }
    }
    return out;
  }
}

// A float as Python's str() writes it: 59.95, 20.5, 59.0.
export function pyFloat(x: number): string {
  return Number.isInteger(x) ? `${x}.0` : String(x);
}
// The radio between the trucks and the gateway (TESTING.md L0.F): telemetry lost, duplicated, late
// (so reordered) and truncated; acks slow and sometimes lost. Applied once for the whole site, so
// every client sees the same stream. Gateway messages (hello, heartbeats, zone and lease events,
// drive rejections) do not pass through it: live they arrived complete and on time.
//
// Every fault is drawn from its own seeded stream and written to the truth log with the truck and seq.
import type { Clock } from '../src/clock.ts';
import type { CommandAck } from '../src/protocol.ts';
import type { Behaviour } from './behaviour.ts';
import type { CommandMatch, Faults, TruthLog } from './faults.ts';
import { Rng } from './rng.ts';

export type Deliver = (line: string) => void;

export class SiteRadio {
  readonly #clock: Clock;
  readonly #b: Behaviour;
  readonly #f: Faults;
  readonly #log: TruthLog;
  readonly #deliver: Deliver;
  readonly #rngTel: Rng;
  readonly #rngAck: Rng;

  constructor(clock: Clock, b: Behaviour, faults: Faults, log: TruthLog, seed: number, deliver: Deliver) {
    this.#clock = clock;
    this.#b = b;
    this.#f = faults;
    this.#log = log;
    this.#deliver = deliver;
    const root = new Rng(seed);
    this.#rngTel = root.fork('radio-telemetry');
    this.#rngAck = root.fork('radio-acks');
  }

  // One telemetry line. The draws are made whether or not each fault is on, so switching one fault
  // on or off never changes another's pattern.
  telemetry(line: string, vehicle: string, seq: unknown): void {
    const r = this.#rngTel, b = this.#b, f = this.#f;
    const lost = r.chance(b.lossProbability);
    const truncate = r.chance(b.truncateProbability);
    const cutAt = r.int(b.truncateMinChars, b.truncateMaxChars);
    const late = r.chance(b.lateProbability);
    const lateBy = Math.round(r.uniform(b.lateMinDelayMs, b.lateMaxDelayMs));
    const dup = r.chance(b.duplicateProbability);
    const dupAfter = Math.round(r.uniform(0, b.duplicateMaxDelayMs));
    const now = this.#clock.now();

    if (f.loss && lost) { this.#log.event(now, vehicle, 'lost', { seq }); return; }
    let sent = line;
    if (f.truncation && truncate && line.length > cutAt) {
      sent = line.slice(0, cutAt);
      this.#log.event(now, vehicle, 'truncated', { seq, chars: cutAt });
    }
    const delay = f.reordering && late ? lateBy : 0;
    if (delay > 0) this.#log.event(now, vehicle, 'late', { seq, byMs: delay });
    this.#at(delay, sent);
    if (f.duplicates && dup) {
      this.#log.event(now, vehicle, 'duplicate', { seq, afterMs: delay + dupAfter });
      this.#at(delay + dupAfter, sent);
    }
  }

  // An ack. Its server_time_ms stays the time the gateway got the command, as live; it arrives
  // later. `n` is the order the command was received in, for CommandMatch.
  ack(line: string, ack: CommandAck, n: number, action: string): void {
    const r = this.#rngAck, b = this.#b, f = this.#f;
    const invalid = ack.reason === 'BAD_JSON' || ack.reason === 'BAD_COMMAND_ID';
    // Commands that act at once (e-stop, leases) were acked within 0.7 s live; the rest up to 2.6 s.
    const immediate = ['ESTOP', 'CLEAR_ESTOP', 'TAKE_CONTROL', 'RELEASE_CONTROL'].includes(action);
    const max = immediate ? b.ackDelayImmediateMaxMs : b.ackDelayMaxMs;
    const delay = invalid
      ? Math.round(r.uniform(b.ackDelayInvalidMinMs, b.ackDelayInvalidMaxMs))
      : Math.round(Math.exp(r.uniform(Math.log(b.ackDelayMinMs), Math.log(max)))); // log-uniform
    const lost = r.chance(b.lostAckProbability);
    if (matches(f.lostAcks, lost, { n, command_id: ack.command_id, vehicle_id: ack.vehicle_id ?? '', action })) {
      this.#log.event(this.#clock.now(), ack.vehicle_id, 'lost_ack', { command_id: ack.command_id, action, status: ack.status });
      return;
    }
    this.#at(f.ackLatency ? delay : 0, line);
  }

  #at(delayMs: number, line: string): void {
    if (delayMs <= 0) this.#deliver(line);
    else this.#clock.setTimeout(() => this.#deliver(line), delayMs);
  }
}

// A command fault switch: off, on at the measured rate (`drawn` is that draw), or a predicate.
export function matches(sw: boolean | CommandMatch | undefined, drawn: boolean, c: Parameters<CommandMatch>[0]): boolean {
  if (!sw) return false;
  if (sw === true) return drawn;
  return sw(c);
}

