p='src/registry.ts'
s=open(p).read()
def rep(a,b,cnt=1):
    global s
    assert s.count(a)==cnt, (a, s.count(a))
    s=s.replace(a,b)
rep("""//      ├──> refused     the safety gate (or a local rule) said no; never sent""","""//      │          └────────────┴──> unverified, when the truck's data is silent or frozen: sent a
//      │                            bounded number of times, then "can't verify" (BLAST.md B16), and
//      │                            checked like any other once believable data returns
//      ├──> refused     the safety gate (or a local rule) said no; never sent""")
