import { readFileSync, readdirSync } from 'node:fs';
const dir = process.argv[2]!;
for (const f of readdirSync(dir)) {
  const p = JSON.parse(readFileSync(`${dir}/${f}`, 'utf8'));
  const self = new Map<number, number>();
  const dt = p.timeDeltas as number[];
  (p.samples as number[]).forEach((id, i) => self.set(id, (self.get(id) ?? 0) + (dt[i] ?? 0)));
  const by = new Map<string, number>();
  for (const n of p.nodes) {
    const k = `${n.callFrame.functionName || '(anon)'} ${n.callFrame.url.split('/').slice(-2).join('/')}:${n.callFrame.lineNumber}`;
    by.set(k, (by.get(k) ?? 0) + (self.get(n.id) ?? 0));
  }
  const total = [...by.values()].reduce((a, b) => a + b, 0);
  console.log(f, 'total ms', (total / 1000).toFixed(0));
  for (const [k, v] of [...by].sort((a, b) => b[1] - a[1]).slice(0, 30)) console.log((v / 1000).toFixed(1).padStart(8), k);
}

